            VertexHlsl,
            VertexMsl,
            VertexGlsl,
            VertexGlslEs),
        new ShaderStageSources(
            PixelSpirv,
            PixelHlsl,
            PixelMsl,
            PixelGlsl,
            PixelGlslEs),
        new ShaderReflection
        {
            Uniforms = new UniformParam[]
            {
                new("World", 0, 64, UniformType.Matrix4x4),
                new("View", 64, 64, UniformType.Matrix4x4),
                new("Projection", 128, 64, UniformType.Matrix4x4),
            },
            Textures = new ResourceBinding[]
            {
            },
            Samplers = new ResourceBinding[]
            {
            },
        }
    );

    /// <summary>Resolves this program's uniform slots against a built pipeline's reflection.</summary>
    public readonly struct ParticleParameters
    {
        internal ParticleParameters(ShaderReflection reflection)
        {
            World = SlotOf(reflection, "World");
            View = SlotOf(reflection, "View");
            Projection = SlotOf(reflection, "Projection");
        }

        public int World { get; }
        public int View { get; }
        public int Projection { get; }

        private static int SlotOf(ShaderReflection reflection, string name)
        {
            foreach (var uniform in reflection.Uniforms)
            {
                if (uniform.Name == name) return uniform.Offset;
            }
            return -1;
        }
    }

    public sealed record ParticleProgram(
        ShaderStageSources Vertex,
        ShaderStageSources Pixel,
        ShaderReflection Reflection)
    {
        public ReadOnlyMemory<byte> VertexSpirv => Vertex.Spirv;
        public ReadOnlyMemory<byte> PixelSpirv => Pixel.Spirv;

        public ParticleParameters Bind() => new(Reflection);
    }
}
